"""Offline code-package update. Database never rolls back with code."""import hashlibimport jsonimport subprocessimport tempfileimport zipfilefrom pathlib import Path, PurePosixPathfrom .operations import create_backup, exclusive_operation, hold_pathALLOWED_TOP_LEVEL = {    "schemas",    "tests",    ".env.example",    "apps",    "config",    "templates",    "static",    "scripts",    "docs",    "manage.py",    "pyproject.toml",    "requirements.lock.txt",    "README.md",}def validate_package(archive, expected_sha256):    archive = Path(archive)    if (        len(expected_sha256) != 64        or hashlib.sha256(archive.read_bytes()).hexdigest() != expected_sha256.lower()    ):        raise ValueError("SHA-256 del paquete incorrecto.")    with zipfile.ZipFile(archive) as package:        manifest = json.loads(package.read("release.json"))        if not manifest.get("version") or not isinstance(manifest.get("files"), dict):            raise ValueError("release.json inválido.")        listed = set(manifest["files"])        actual = {n for n in package.namelist() if not n.endswith("/") and n != "release.json"}        if actual != listed:            raise ValueError("Manifest et fichiers diffÃ¨rent.")        for name, digest in manifest["files"].items():            path = PurePosixPath(name)            if (                path.is_absolute()                or ".." in path.parts                or not path.parts                or path.parts[0] not in ALLOWED_TOP_LEVEL                or "\\" in name                or ":" in name            ):                raise ValueError("Ruta de paquete no permitida.")            if hashlib.sha256(package.read(name)).hexdigest() != digest:                raise ValueError("Hash interno de paquete incorrecto.")        return manifestdef apply_update(archive, expected_sha256, root, database, key, *, offline, runner=None):    if not offline:        raise ValueError("ActualizaciÃ³n requiere servicio y workers detenidos (--offline).")    manifest = validate_package(archive, expected_sha256)    root = Path(root).resolve()    database = Path(database).resolve()    runner = runner or (lambda arguments: subprocess.run(arguments, cwd=root, check=True))    import sys    with exclusive_operation(database), tempfile.TemporaryDirectory() as directory:        directory = Path(directory)        backup = (            root            / "backups"            / ("pre-update-" + manifest["version"].replace("/", "_").replace("\\", "_") + ".btpv")        )        if backup.exists():            raise ValueError(                "Ya existe copia previa de esta versiÃ³n; use identificador de versiÃ³n Ãºnico."            )        create_backup(database, backup, key)        previous = {}        with zipfile.ZipFile(archive) as package:            for name in manifest["files"]:                target = (root / name).resolve()                if not target.is_relative_to(root):                    raise ValueError("Ruta fuera de instalaciÃ³n.")                previous[name] = target.read_bytes() if target.is_file() else None                target.parent.mkdir(parents=True, exist_ok=True)                target.write_bytes(package.read(name))        try:            runner([sys.executable, str(root / "manage.py"), "migrate", "--noinput"])            runner([sys.executable, str(root / "manage.py"), "check"])            runner([sys.executable, str(root / "manage.py"), "collectstatic", "--noinput"])        except Exception:            for name, data in previous.items():                target = root / name                if data is None:                    target.unlink(missing_ok=True)                else:                    target.write_bytes(data)            hold_path(database).write_text(                "ActualizaciÃ³n fallida: cÃ³digo revertido; BD no revertida. Revisar compatibilidad de migraciones y conciliar antes de arrancar.",                encoding="utf-8",            )            raise    return manifest